-- sys_api_config
CREATE TABLE IF NOT EXISTS "sys_api_config" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "api_name" varchar(100) NOT NULL,
  "api_code" varchar(100) DEFAULT NULL,
  "req_method" varchar(20) NOT NULL,
  "url_path" varchar(255) NOT NULL,
  "api_version" varchar(20) DEFAULT 'v1.0.0',
  "module_code" varchar(50) NOT NULL,
  "service_id" varchar(100) DEFAULT NULL,
  "auth_flag" smallint NOT NULL DEFAULT 1,
  "encrypt_flag" smallint NOT NULL DEFAULT 0,
  "tenant_flag" smallint NOT NULL DEFAULT 1,
  "limit_flag" smallint NOT NULL DEFAULT 0,
  "sensitive_fields" text,
  "status" smallint NOT NULL DEFAULT 1,
  "remark" varchar(500) DEFAULT NULL,
  "create_by" varchar(64) DEFAULT NULL,
  "create_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "update_by" varchar(64) DEFAULT NULL,
  "update_time" timestamp DEFAULT CURRENT_TIMESTAMP,
  "tenant_id" bigint DEFAULT NULL,
  "del_flag" bigint NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
COMMENT ON TABLE "sys_api_config" IS 'REST接口配置管理表';
COMMENT ON COLUMN "sys_api_config"."id" IS '主键ID';
COMMENT ON COLUMN "sys_api_config"."api_name" IS '接口名称 (如:查询用户信息)';
COMMENT ON COLUMN "sys_api_config"."api_code" IS '接口编码 (用于程序逻辑引用)';
COMMENT ON COLUMN "sys_api_config"."req_method" IS '请求方式 (GET, POST, PUT, DELETE, ALL)';
COMMENT ON COLUMN "sys_api_config"."url_path" IS '接口请求路径 (支持Ant风格, 如 /api/user/**)';
COMMENT ON COLUMN "sys_api_config"."api_version" IS '接口版本号';
COMMENT ON COLUMN "sys_api_config"."module_code" IS '所属业务模块 (如: sys, order, pay)';
COMMENT ON COLUMN "sys_api_config"."service_id" IS '所属微服务ID (若为微服务架构)';
