INSERT INTO "ai_page_template" (id,template_key,template_name,description,icon,system_prompt,schema_hint,default_config,enabled,sort,is_builtin,codegen_type,create_by,create_time,create_dept,update_by,update_time,del_flag) VALUES
	 (1,'simple-crud','标准 CRUD','适合平坦型数据的属性增删改查，支持搜索、表格列表、弹窗/抒屉表单编辑','mdi:table','当前模板为「标准 CRUD」，请确保：
1. columnsSchema 包含内容列 + 操作列(actions)
2. editSchema 简洁清晰，不要嵌套
3. modalType 默认为 drawer
4. 尽量岑减搜索条件，保留最常用的3-5个',NULL,'{"modalType": "drawer", "modalWidth": "800px", "editGridCols": 1, "searchGridCols": 4}',1,1,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-26 17:20:22',0),
	 (2,'tree-crud','树形 CRUD','适合具有父子层级结构的数据，如部门结构、分类管理等，左树右表格布局','mdi:file-tree','当前模板为「树形 CRUD」，请确保：
1. editSchema 中必须包含 parentId 字段（type: treeSelect）
2. editSchema 中包含 sort 排序字段
3. columnsSchema 中包含 层级深度或父层名称列
4. apiConfig 中包含 tree 接口（查询树形结构）
5. treeConfig 配置：{"keyField": "id", "parentField": "parentId", "labelField": "name"}
6. 数据必须有 parent_id 字段，不要导入进 editSchema
7. 模式必须为 modal','{"treeConfig": {"keyField": "id", "labelField": "name", "parentField": "parentId"}}','{"modalType": "modal", "modalWidth": "600px", "editGridCols": 1, "searchGridCols": 3}',1,2,1,'TEMPLATE',NULL,'2026-04-26 17:05:23',NULL,1,'2026-04-30 15:53:18',0);

INSERT INTO "ai_prompt_template" (id,tenant_id,template_name,template_code,usage_scene,business_category,domain_category,template_tags,description,prompt_content,example_input,status,del_flag,is_recommended,sort_order,use_count,test_count,download_count,remark,create_by,create_time,create_dept,update_by,update_time) VALUES
	 (1910000000000000001,1,'数据驱动大屏生成通用模板','dashboard_generate_default','dashboard_generate','经营分析','数据大屏','数据绑定,经营监控,可视化','适用于基于业务定义和数据集生成可落地的大屏，强调动态数据绑定和组件布局。','请基于当前业务定义、数据集字段和运行时样例生成数据大屏。要求：
1. 优先使用真实 datasetId 生成动态数据组件，指标、趋势、排行、表格、地图尽量输出 request.datasetId、request.datasetFields 和 request.datasetMapping。
2. 先规划顶部 KPI、核心趋势、分类排行、明细/告警等区域，再选择合适组件，避免只生成装饰元素。
3. 字段只能使用上下文中出现的 fieldName，不要使用字段中文名作为 request 字段。
4. 敏感或隐藏字段按上下文安全规则处理，不能展示原始敏感值。
5. 如果数据集不可用，可以静态兜底，但标题、说明和组件含义必须贴合业务目标。
6. 输出必须是系统要求的合法 JSON，不要添加 Markdown 包裹或额外解释。','生成经营监控大屏，突出核心指标、趋势分析和异常预警。','0',0,'1',1,8,18,5,'系统内置最佳实践模板',1,'2026-05-19 15:22:05',1,1,'2026-07-13 17:59:05');

