  SELECT id FROM sys_resource
  WHERE tenant_id = 1 AND resource_type = 1 AND path = '/system' AND del_flag = 0
  ORDER BY id LIMIT 1
)), 0), 1, 95,
       '/system/collaboration', NULL, 0, '_self', 0, 1, 1,
       NULL, 'ionicons5:GitNetworkOutline', 0, 1, '企业协同集成管理目录',
       1, NOW(), 1, NOW(), 1, 'pc'
